from pathlib import Path

path = Path("client/src/pages/AccountFeaturePages.tsx")
text = path.read_text()
start = text.index("export function BuyerSearchAlertsPage()")
end = text.index("\nexport function BuyerReminderDashboardPage()", start)
new_component = '''export function BuyerSearchAlertsPage() {
  type AlertEdit = { id: number; query: string; categorySlug: string; minNaira: string; maxNaira: string; condition: "" | "NEW" | "LIKE_NEW" | "USED_GOOD" | "USED_FAIR" | "REFURBISHED"; verified: boolean; notifyInApp: boolean; notifyEmail: boolean };
  const alerts = trpc.searchAlerts.listMine.useQuery();
  const categories = trpc.marketplace.categories.useQuery();
  const utils = trpc.useUtils();
  const [editing, setEditing] = useState<AlertEdit | null>(null);
  const update = trpc.searchAlerts.update.useMutation({ onSuccess: () => { toast.success("Saved search updated."); setEditing(null); void utils.searchAlerts.listMine.invalidate(); }, onError: error => toast.error(error.message) });
  const cancel = trpc.searchAlerts.cancel.useMutation({ onSuccess: () => { toast.success("Saved search removed."); void utils.searchAlerts.listMine.invalidate(); }, onError: error => toast.error(error.message) });
  const activeAlerts = alerts.data?.filter(alert => alert.status === "ACTIVE") ?? [];
  const formatCriteria = (alert: (typeof activeAlerts)[number]) => [alert.categorySlug ? alert.categorySlug.replaceAll("-", " ") : null, alert.minKobo != null ? `from ${naira(alert.minKobo)}` : null, alert.maxKobo != null ? `up to ${naira(alert.maxKobo)}` : null, alert.condition ? alert.condition.replaceAll("_", " ").toLocaleLowerCase() : null, alert.verified ? "verified sellers" : null].filter(Boolean).join(" · ");
  const beginEdit = (alert: (typeof activeAlerts)[number]) => setEditing({ id: alert.id, query: alert.query, categorySlug: alert.categorySlug ?? "", minNaira: alert.minKobo == null ? "" : String(alert.minKobo / 100), maxNaira: alert.maxKobo == null ? "" : String(alert.maxKobo / 100), condition: (alert.condition ?? "") as AlertEdit["condition"], verified: alert.verified, notifyInApp: alert.notifyInApp, notifyEmail: alert.notifyEmail });
  const saveEdit = (event: FormEvent) => { event.preventDefault(); if (!editing) return; if (!editing.notifyInApp && !editing.notifyEmail) { toast.error("Choose at least one notification channel."); return; } const min = editing.minNaira.trim() ? Math.round(Number(editing.minNaira) * 100) : undefined; const max = editing.maxNaira.trim() ? Math.round(Number(editing.maxNaira) * 100) : undefined; if (min !== undefined && (!Number.isFinite(min) || min < 0) || max !== undefined && (!Number.isFinite(max) || max <= 0)) { toast.error("Enter valid price limits."); return; } update.mutate({ id: editing.id, query: editing.query, categorySlug: editing.categorySlug || undefined, minKobo: min, maxKobo: max, condition: editing.condition || undefined, verified: editing.verified, notifyInApp: editing.notifyInApp, notifyEmail: editing.notifyEmail }); };
  const removeAlert = (id: number) => { if (window.confirm("Remove this saved search? You will no longer receive alerts for it.")) cancel.mutate({ id }); };
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#e31b23]">MY ACCOUNT</p><div className="mt-2 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="text-3xl font-extrabold">Saved search alerts</h1><p className="mt-2 max-w-2xl text-sm text-slate-600">Manage the searches you asked us to watch. We will notify you when an eligible listing is published.</p></div><Link href="/explore"><Button className="bg-[#e31b23]"><Search size={16} className="mr-2"/>Find more items</Button></Link></div><section className="mt-7 rounded-3xl bg-[#eaf7ef] p-5 ring-1 ring-[#00843d]/15 sm:p-6"><div className="flex items-start gap-3"><div className="rounded-2xl bg-white p-3 text-[#00843d] shadow-sm"><BellRing size={22}/></div><div><p className="font-extrabold text-[#08243b]">Stay ahead of new campus listings</p><p className="mt-1 text-sm leading-6 text-slate-600">Alerts match your saved search words and filters. You can edit delivery channels at any time; saving one never reserves stock.</p></div></div></section><section aria-labelledby="active-search-alerts" className="mt-7"><div className="flex items-center justify-between gap-3"><div><h2 id="active-search-alerts" className="text-xl font-black">Active alerts</h2><p className="mt-1 text-sm text-slate-500">{activeAlerts.length} active {activeAlerts.length === 1 ? "search" : "searches"}</p></div></div>{alerts.isLoading ? <div className="mt-4 grid gap-4 lg:grid-cols-2">{[1, 2].map(item => <div key={item} className="h-52 animate-pulse rounded-2xl bg-slate-100 motion-reduce:animate-none" aria-hidden="true"/> )}</div> : alerts.isError ? <div className="mt-4 rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]" role="alert"><p className="font-extrabold">We could not load your saved searches.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => alerts.refetch()}>Try again</Button></div> : activeAlerts.length ? <div className="mt-4 grid gap-4 lg:grid-cols-2">{activeAlerts.map(alert => <article key={alert.id} className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200">{editing?.id === alert.id ? <form onSubmit={saveEdit} className="space-y-4"><div className="flex items-center justify-between gap-3"><h3 className="text-lg font-extrabold text-[#08243b]">Edit saved search</h3><span className="rounded-full bg-[#eaf7ef] px-2.5 py-1 text-xs font-black text-[#006b32]">ACTIVE</span></div><label className="block text-sm font-bold">Search words<input required minLength={2} maxLength={120} value={editing.query} onChange={event => setEditing({ ...editing, query: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 p-3 font-normal outline-none focus:border-[#00843d]"/></label><label className="block text-sm font-bold">Category<select value={editing.categorySlug} onChange={event => setEditing({ ...editing, categorySlug: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 bg-white p-3 font-normal outline-none focus:border-[#00843d]"><option value="">All categories</option>{categories.data?.map(category => <option key={category.id} value={category.slug}>{category.name}</option>)}</select></label><div className="grid gap-3 sm:grid-cols-2"><label className="block text-sm font-bold">Minimum price (₦)<input inputMode="decimal" value={editing.minNaira} onChange={event => setEditing({ ...editing, minNaira: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 p-3 font-normal outline-none focus:border-[#00843d]" placeholder="No minimum"/></label><label className="block text-sm font-bold">Maximum price (₦)<input inputMode="decimal" value={editing.maxNaira} onChange={event => setEditing({ ...editing, maxNaira: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 p-3 font-normal outline-none focus:border-[#00843d]" placeholder="No maximum"/></label></div><label className="block text-sm font-bold">Condition<select value={editing.condition} onChange={event => setEditing({ ...editing, condition: event.target.value as AlertEdit["condition"] })} className="mt-2 w-full rounded-xl border border-slate-200 bg-white p-3 font-normal outline-none focus:border-[#00843d]"><option value="">Any condition</option><option value="NEW">New</option><option value="LIKE_NEW">Like new</option><option value="USED_GOOD">Used — good</option><option value="USED_FAIR">Used — fair</option><option value="REFURBISHED">Refurbished</option></select></label><label className="flex items-center gap-3 rounded-xl bg-slate-50 p-3 text-sm font-semibold"><input type="checkbox" className="h-4 w-4 accent-[#00843d]" checked={editing.verified} onChange={event => setEditing({ ...editing, verified: event.target.checked })}/>Verified sellers only</label><fieldset className="rounded-xl border border-slate-200 p-4"><legend className="px-1 text-sm font-extrabold">Notification settings</legend><label className="mt-1 flex items-start gap-3 text-sm"><input type="checkbox" className="mt-1 h-4 w-4 accent-[#00843d]" checked={editing.notifyInApp} onChange={event => setEditing({ ...editing, notifyInApp: event.target.checked })}/><span><b>In-app notifications</b><span className="block text-xs font-normal text-slate-500">Show matching listings in your Notifications dashboard.</span></span></label><label className="mt-3 flex items-start gap-3 text-sm"><input type="checkbox" className="mt-1 h-4 w-4 accent-[#00843d]" checked={editing.notifyEmail} onChange={event => setEditing({ ...editing, notifyEmail: event.target.checked })}/><span><b>Email notifications</b><span className="block text-xs font-normal text-slate-500">Email delivery is attempted only when the marketplace email provider is configured.</span></span></label></fieldset><div className="flex flex-wrap gap-2"><Button type="submit" className="bg-[#00843d]" disabled={update.isPending}>{update.isPending ? "Saving…" : "Save changes"}</Button><Button type="button" variant="outline" onClick={() => setEditing(null)} disabled={update.isPending}>Cancel</Button></div></form> : <><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-start gap-3"><div className="rounded-xl bg-[#eaf7ef] p-2.5 text-[#00843d]"><Bell size={18}/></div><div className="min-w-0"><h3 className="break-words text-lg font-extrabold text-[#08243b]">{alert.query}</h3><p className="mt-1 text-sm capitalize text-slate-500">{formatCriteria(alert) || "All marketplace listings"}</p></div></div><span className="shrink-0 rounded-full bg-[#eaf7ef] px-2.5 py-1 text-xs font-black text-[#006b32]">ACTIVE</span></div><div className="mt-5 grid gap-2 border-t border-slate-100 pt-4 text-xs text-slate-500 sm:grid-cols-2"><p className="flex items-center gap-2"><CalendarClock size={14} className="text-[#00843d]"/>Created {new Date(alert.createdAt).toLocaleDateString("en-NG", { day: "numeric", month: "short", year: "numeric" })}</p><p>{alert.lastNotifiedAt ? `Last match ${new Date(alert.lastNotifiedAt).toLocaleDateString("en-NG", { day: "numeric", month: "short" })}` : "No matching listing yet"}</p></div><div className="mt-5 flex flex-wrap gap-2"><Link href={`/explore?q=${encodeURIComponent(alert.query)}`}><Button size="sm" variant="outline">View results</Button></Link><Button size="sm" variant="outline" onClick={() => beginEdit(alert)}><Pencil size={15} className="mr-2"/>Edit alert</Button><Button size="sm" variant="outline" className="text-[#b91c1c] hover:bg-[#fff3f3]" disabled={cancel.isPending} onClick={() => removeAlert(alert.id)}><Trash2 size={15} className="mr-2"/>{cancel.isPending ? "Removing…" : "Remove alert"}</Button></div></>}</article>)}</div> : <div className="mt-4 rounded-3xl border border-dashed border-slate-300 bg-white p-10 text-center"><BellRing className="mx-auto text-[#00843d]" size={30}/><h3 className="mt-3 font-extrabold text-[#08243b]">No active saved searches</h3><p className="mx-auto mt-1 max-w-md text-sm leading-6 text-slate-500">When a search returns no results, choose Notify me to save it here and receive a dashboard alert when new matching items are published.</p><Link href="/explore"><Button className="mt-5 bg-[#e31b23]">Browse the marketplace</Button></Link></div>}</section></main></Gate>;
}'''
path.write_text(text[:start] + new_component + text[end:])
print("updated saved-search dashboard")
''
